def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1)) == 0

def next_power_of_two(n):
    p = 1
    while p < n:
        p *= 2
    return p

def extended_gcd(a, b):
    old_r, r = a, b
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
        old_t, t = t, old_t - q * t
    return (old_r, old_s, old_t)

def primes_up_to(n):
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i in range(n + 1) if sieve[i]]

def count_primes_up_to(n):
    if n < 2:
        return 0
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return sum(sieve)

def is_palindrome_in_base(n, base):
    if n == 0:
        digits = [0]
    else:
        digits = []
        x = n
        while x > 0:
            digits.append(x % base)
            x //= base
    return digits == digits[::-1]

def int_to_binary_string(n):
    if n == 0:
        return "0"
    return bin(n)[2:]

def int_to_hex_string(n):
    if n == 0:
        return "0"
    return format(n, 'x')

def digit_reverse_sum(n):
    rev = int(str(n)[::-1])
    return n + rev

def digits_in_factorial(n):
    fact = 1
    for k in range(2, n + 1):
        fact *= k
    return len(str(fact))

def sum_of_first_n_primes(n):
    if n <= 0:
        return 0
    primes = []
    candidate = 2
    while len(primes) < n:
        is_prime = True
        for p in primes:
            if p * p > candidate:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1
    return sum(primes)

def integer_cube_root(n):
    lo, hi = 0, max(1, n)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** 3 <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo
